export const getGetStoreCapturesUrl = (id: string,
    params?: GetStoreCapturesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/stores/${id}/captures?${stringifiedParams}` : `/api/stores/${id}/captures`
}

